"""Tests for tasks_api.queries."""

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query


NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _make_task(id, title="Task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
               due_at=None, tags=None, created_at=None):
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        created_at=created_at or NOW,
        tags=tags or [],
    )


class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101, "abc"])
    def test_invalid_limit(self, limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalizes(self):
        q = TaskQuery(tag="  MyTag  ")
        assert q.tag == "mytag"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_strips_whitespace(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_search_empty_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_make_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false(self):
        page = TaskPage(items=[_make_task(1), _make_task(2)], total=2, limit=10, offset=0)
        assert page.has_more is False


class TestApplyQueryFilters:
    @pytest.fixture
    def tasks(self):
        past = NOW - timedelta(days=5)
        future = NOW + timedelta(days=5)
        return [
            _make_task(1, "Buy milk", status=TaskStatus.PENDING, tags=[Tag("shopping")],
                       due_at=past, created_at=NOW - timedelta(hours=3)),
            _make_task(2, "Write tests", status=TaskStatus.DONE, tags=[Tag("code")],
                       created_at=NOW - timedelta(hours=2)),
            _make_task(3, "Read book", status=TaskStatus.PENDING, tags=[Tag("leisure")],
                       due_at=future, created_at=NOW - timedelta(hours=1)),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 3
        assert len(page.items) == 3

    def test_filter_by_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert page.total == 2
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_by_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].title == "Write tests"

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 1
        assert page.items[0].title == "Buy milk"

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="milk"), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="WRITE"), NOW)
        assert page.total == 1

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].title == "Buy milk"

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # Tasks 2 (done, no due) and 3 (future due) are not overdue
        assert page.total == 2


class TestApplyQuerySort:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Banana", priority=TaskPriority.LOW,
                       created_at=NOW - timedelta(hours=2)),
            _make_task(2, "Apple", priority=TaskPriority.HIGH,
                       created_at=NOW - timedelta(hours=1)),
            _make_task(3, "Cherry", priority=TaskPriority.MEDIUM,
                       due_at=NOW + timedelta(days=1),
                       created_at=NOW),
        ]

    def test_sort_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

    def test_sort_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW
        ]

    def test_sort_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Task 3 has due_at, tasks 1 and 2 have None (sort last)
        assert page.items[0].id == 3


class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_make_task(i, f"Task {i}", created_at=NOW + timedelta(minutes=i)) for i in range(1, 11)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=20), NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

"""Tests for tasks_api.repository (InMemoryTaskRepository + normalize_tags)."""

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_add_and_get(self, repo):
        task = Task(id=1, title="Test task")
        repo.add(task)
        retrieved = repo.get(1)
        assert retrieved is not None
        assert retrieved.title == "Test task"

    def test_add_duplicate_raises(self, repo):
        task = Task(id=1, title="Test")
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(Task(id=1, title="Duplicate"))

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_list_returns_all(self, repo):
        repo.add(Task(id=1, title="First"))
        repo.add(Task(id=2, title="Second"))
        tasks = list(repo.list())
        assert len(tasks) == 2

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_update_existing(self, repo):
        task = Task(id=1, title="Original")
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(Task(id=999, title="Missing"))

    def test_delete_existing(self, repo):
        repo.add(Task(id=1, title="To delete"))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_string_values_wrapped(self):
        result = normalize_tags(["hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_tag_values_passthrough(self):
        result = normalize_tags([Tag("alpha"), Tag("beta")])
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_deduplication(self):
        result = normalize_tags(["Hello", "hello", "HELLO"])
        assert len(result) == 1
        assert result[0].name == "hello"

    def test_mixed_types(self):
        result = normalize_tags([Tag("foo"), "FOO", "bar"])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["beta", "alpha", "beta", "gamma"])
        assert [t.name for t in result] == ["beta", "alpha", "gamma"]

